shortcuts.codeOnPrepare:
// To Do List for CrossPoint: opens the To Do List card on your reader
// with the shared text filled in. Then press "Save to reader".
const address = (getVariable('readerAddress') || '').trim() || 'crosspoint.local';
let title = (getVariable('noteTitle') || '').trim();
let text = (getVariable('noteText') || '').replace(/\r/g, '').trim();

// Some apps repeat the title as the first line of the text.
if (title && text.split('\n')[0].trim() === title) {
  text = text.split('\n').slice(1).join('\n').trim();
}

if (!title && !text) {
  showToast('Nothing to send');
} else {
  const host = address.replace(/^https?:\/\//, '').replace(/\/+$/, '');
  const base = 'http://' + host + '/files';
  const url = title
    ? base + '#title=' + encodeURIComponent(title) + '&body=' + encodeURIComponent(text)
    : base + '#note=' + encodeURIComponent(text);
  openUrl(url);
}
